quests[10447] = { id = 10447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Code", description = "They're building a second mana bomb in the courtyard.  My intel suggests that the final code for the bomb is being held by Sharth Voldoun, the overseer of the project at Firewing Point.\n\n{name}, you have to go back in there and retrieve the final code from him.  He keeps himself to the top of the highest spire.\n\nTake the final code to the mana bomb that they're working on in the central courtyard and set it off.\n\nOnly then will we be certain that Stonebreaker Hold is safe.", completion = "YOU DID IT!  YOU SAVED US!  YOU SAVED STONEBREAKER HOLD!!\n\nWith their forces decimated, their leader dead and the mana bomb destroyed, we can all breathe much easier now.\n\n{name}, I've never seen such selflessness... such heroism!  Please, accept this on behalf of all of us.", objectives = "Sergeant Chawni wants you to use the Final Code Sheet to set off the Mana Bomb. Then report back to Tooki at Stonebreaker Hold in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10448] = { id = 10448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Stonebreaker Camp", description = "This calls for immediate action!\n\nWe have someone out in the field closer to Firewing Point that I want you to speak with.  She'll have a better idea of what our next step should be.\n\nReport to Sergeant Chawni out at Stonebreaker Camp and apprise her of the situation.\n\nTake the road north out of the hold.  From the middle of Tuurem, follow the road to the east.  You'll find the camp on the bank of the river that lies just southwest of Firewing Point.\n\nGood luck, {name}.", completion = "Bomb parts. So my suspicions were true.  That's not something that I wanted to be right about.\n\nOk, you and I have some grim business ahead of us then.", objectives = "Tooki wants you to report to Sergeant Chawni at Stonebreaker Camp in Terokkar Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10449] = { id = 10449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apothecary Zelana", description = "Apethecary Zelana has been studying the beasts of Hellfire Peninsula in the field.  She wants a sample of the blood you gathered; with luck, she might discover what turned those Bonechewer freaks' skins red!\n\nZelana is at Reaver's Fall, southeast of Thrallmar.  Follow the road east and when you see a destroyed, green-glowing hunk of metal, you're there.  She has a camp set up behind the wyverns.", progress = "It is my honor to serve the wishes of the Horde.  How might I aid you?", completion = "Ah, yes.  The blood of the Bonechewer clan.  I am very curious about these orcs... they are still the depraved fiends of the past, but their strength and power is greater than what I had heard...\n\nWell, let us begin, shall we?", objectives = "Vertok Axebreaker in Thrallmar wants you to bring Bonechewer Blood Samples to Apothecary Zelana at Reaver's Fall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10450] = { id = 10450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonechewer Blood", description = "Bonechewers!  They should all die!  The sight of their red skin and depravity makes my blood boil!\n\nI have a mission for you, {name}.  Kill Bonechewer orcs and collect their vile blood.  There is an apothecary who needs the blood for her tests, so we can discover how these orcs fell to the demon taint, a taint from which we so recently freed ourselves.\n\nBonechewers scavenge near the ruined battlements along the Path of Glory, to the south.  Return to me when your mission is complete.", progress = "Did you face the bonechewers, {name}.  I hope their blood was spilled in great gouts!", completion = "Hah!  So you did meet the bonechewers, our depraved cousins.  Well done, {name}.  My only regret is that more of them could not lay down their lives and spill their blood, to cool my outrage!", objectives = "Bring 12 Bonechewer Blood Vials to Vurtok Axebreaker in Thrallmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10451] = { id = 10451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Coilskar Cistern", description = "Thank the Earthmother! I parted ways with the others several days ago. I was intent on discovering the source of the disturbance that the spirits of water were feeling. My search led me to Coilskar where I discovered that the naga were befouling the water supply of Shadowmoon Valley.\n\nUnfortunately, I was discovered and taken prisoner. There's no telling what ghastly things they had in store for me.\n\nWe must leave this place! Help me escape and then seek out Torlok at the Altar of Damnation.", completion = "Praise the Earthmother. I am certain that Wilda will find her way home. Please accept this as a token of our appreciation.", objectives = "Escort Earthmender Wilda out of Coilskar Cistern and then seek out Earthmender Torlok at the Altar of Damnation, found at the western outskirts of the Hand of Gul'dan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10454] = { id = 10454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - OFF THE RAILS" }
quests[10455] = { id = 10455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Encroaching Wilderness", description = "We've been growing the Living Grove at an accelerated rate, but somehow the lynxes there have become lost to our control.\n\nWhere once their population was stable, the grovestalker lynxes are now beginning to encroach upon Sylvanaar, and there have been a number of unpleasant incidents of late.\n\nI suspect that the arakkoa of Veil Lashh are somehow behind it, but the immediate issue is with the lynxes themselves.\n\nI would be most grateful if you would help us to deal with this situation.", completion = "That was fast.  Are you sure that you dealt with as many as was necessary?\n\nExcellent, there's something else that you can help us with if you are willing?", objectives = "Slay 12 Grovestalker Lynxes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10456] = { id = 10456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marauding Wolves", description = "The filthy races of the Horde have taken over a settlement to the east.  They've brought with them a large pack of the dire wolves that they prefer to use as mounts and sentries.\n\nThese sentries have been marauding across the bridge that separates us.  They've been stalking our fey drakes, which are critical to the pollination of the Living Grove.\n\nUse the east exit to traverse the bridge over Bloodmaul Ravine that leads to the Jagged Ridge to the east, and bring me their tails as proof!", progress = "I cannot stress strongly enough the need for those Thunderlord dire wolves to be dealt with.  Their very existence endangers the stability of the Living Grove and all of our work here.", completion = "Good.  I'll see if I can fashion something useful from these tails.\n\nNo doubt that the Horde will find a way to replenish the numbers of their wolf pack, but for now we can breathe a little easier.\n\n{name}, if you are willing there's something else that I would ask of you in defense of Sylvanaar and the Living Grove.", objectives = "Collect 4 Thunderlord Dire Wolf Tails.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10457] = { id = 10457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protecting Our Own", description = "Though you've done a great deal of good work in defense of our new home here, I still feel that the Living Grove needs more protection.\n\nPlease, take this small tree bough that I have imbued with the force of nature.  When used upon the seedlings that I have planted out in the grove, it will call down a storm to accelerate the growth of a treant defender.\n\nThese treants are critical to the defense of the grove, especially if you choose not to make Sylvanaar your home for long.", progress = "How fares the bolstering of the Living Grove's defenses?\n\nWith the intentions of the arakkoa at Veil Lashh unknown, and the Horde just on the other side of the ravine, I fear that if we do not move quickly we will find ourselves in a poor situation to protect our new home and our work in the grove.", completion = "Now that you have strengthened the grove's defenses, I feel much safer.\n\nYou've earned our thanks and appreciation, {name}.\n\nOf course, it just occurred to me that there's something else that we need to take care of!", objectives = "Use Rina's Bough on 5 of the Grove Seedlings to summon forth defenses for the Living Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10458] = { id = 10458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged Spirits of Fire and Earth", description = "We must try and make amends. We must commune with the elements of this region and see if anything can be done!\n\nI grant you the totem of spirits, {race}. If you slay an enraged elemental spirit in close proximity of the totem, it will consume the elemental's soul. You must use the totem to consume many souls before you may return to me.\n\nDo this for the spirits of fire and earth first. Return to me when the totem is full.", progress = "I fear that this land may be without hope.", completion = "When all of the elemental souls of this region have been placed inside the totem, we will commune with them and find out if anything can be done for Shadowmoon Valley.", objectives = "Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley wants you to use the Totem of Spirits to capture 8 Earthen Souls and 8 Fiery Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10459] = { id = 10459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revered Among the Cenarion Expedition", description = "We've taken notice of your accomplishments, {name}.  What you've done for us goes beyond what we expect from our allies.\n\nI've a special request to ask of you, but I must test your dedication first.", objectives = "Ysiel Windsinger at the Cenarion Refuge wants you to become revered with the Cenarion Expedition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[10460] = { id = 10460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defender's Pledge", objectives = "Are you sure this is the path you seek to take, {name}?  This is not a decision you ought to take lightly.\n\nThis ring is imbued with a droplet from the Well of Eternity.  It will grow in power as you prove yourself to the Scale of the Sands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
