quests[10464] = { id = 10464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sage's Vow", description = "You've made your pledge, {class}.  Now it is up to you to see it through.\n\nServe the Scale of the Sands well and you will be rewarded.\n\nFail and the timeline as we know it will be unravelled!", progress = "You continue to serve us well, {name}.", completion = "You've proved your worth, {race}.  Up to a certain point, at least.\n\nThe favor of Nozdormu's prime mate is not obtained easily.", objectives = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Honored reputation with the Scale of the Sands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
